select `p`.*, `p`.`region` as `geospatial:key:0`, `p`.`id` as `geospatial:key:1` from (select (CASE WHEN (`occurrences`.`region` = ?) THEN `occurrences`.`id` END) AS `id`, (CASE WHEN (`occurrences`.`region` = ?) THEN st_astext(`occurrences`.`geometry`) END) AS `geometry` from `occurrences` where `occurrences`.`region` = ? and PtDistWithin(`occurrences`.`geometry`, MakePoint(?, ?, 4326), ?, 1)) as `p` where `p`.`geometry` is not null order by `p`.`region` desc, `p`.`id` asc limit ? offset ?
